        t: "Steeds komt terug dat het hart van de farao hard wordt. De Statenvertaling gebruikt woorden als verharden, verzwaren, verstokken en verstijven. Soms staat er dat de farao zelf zijn hart verzwaarde (Exodus 8:15, 32). Soms staat er dat de HEERE het deed (Exodus 9:12; 10:20, 27). Al vóór de plagen had God gezegd: ‘Doch Ik zal Farao’s hart verharden’ (Exodus 7:3). De tekst noemt beide naast elkaar, en pleit de farao niet vrij: na de hagel ‘verzondigde hij zich verder’ (Exodus 9:34). Later zeggen de priesters en waarzeggers van de Filistijnen: ‘Waarom toch zoudt gijlieden uw hart verzwaren, gelijk de Egyptenaars en Farao hun hart verzwaard hebben?’ (1 Samuël 6:6).",
