        t: "Toen Mozes naar Egypte terugging, gaf God hem al de boodschap mee: ‘Mijn zoon, Mijn eerstgeborene, is Israël’ (Exodus 4:22). Na de uittocht zegt God: ‘Heilig Mij alle eerstgeborenen’ (Exodus 13:2). De eerstgeboren zonen van Israël moesten worden gelost, dat is: vrijgekocht. De reden staat erbij: de HEERE doodde de eerstgeborenen van Egypte toen de farao het volk niet liet gaan (Exodus 13:13, 15). Ouders moesten hun kinderen uitleggen waarom: ‘De HEERE heeft ons door een sterke hand uit Egypte, uit het diensthuis, uitgevoerd’ (Exodus 13:14). Zo brachten later ook Jozef en Maria de Heere Jezus naar Jeruzalem, naar wat geschreven is: ‘Al wat mannelijk is, dat de moeder opent, zal den Heere heilig genaamd worden’ (Lukas 2:23).",
