        kop: "Waar en wanneer",
        t: "Het volk trekt over ‘tegenover Jericho’ (Jozua 3:16). Het water blijft staan ‘zeer verre van de stad Adam af, die ter zijde van Sarthan ligt’; een afstand noemt de Bijbel niet. Gilgal ligt ‘aan het oosteinde van Jericho’ (Jozua 4:19). Gilgal en Sittim staan op de kaart als waarschijnlijke plaatsen; de precieze plek van de doortocht noemt de Bijbel niet. De datering is een reconstructie: veertig jaar na de uittocht, die op grond van 1 Koningen 6:1 rond 1446 v.Chr. wordt gedateerd, dus ca. 1406 v.Chr. Wie de uittocht in de 13e eeuw v.Chr. dateert, plaatst de intocht rond 1230–1200 v.Chr.",
