        t: "De Filistijnen legeren zich ‘tussen Socho en tussen Azeka’ in Juda (17:1); Israël staat in het eikendal. Het Eikdal is op de kaart identificeerbaar, net als Gath, de stad van Goliath, en Ekron, tot waar Israël de Filistijnen achtervolgt (17:52). Een jaartal staat er niet bij. David is nog ‘een jongeling’ (17:33) en wordt op zijn dertigste koning (2 Samuël 5:4), in de gangbare chronologie ca. 1010 v.Chr. Op de tijdlijn staat het gevecht als reconstructie rond 1025 v.Chr., met het label onzeker. Hoe oud David precies was, zegt de Bijbel niet.",
