        t: "In de woestijn maakte Mozes een koperen slang en zette die op een stang; wie gebeten was en haar aanzag, bleef leven (Numeri 21:8–9). Tot in de tijd van Hizkia brandden de Israëlieten er reukwerk voor. Daarom verbrijzelt Hizkia haar en noemt haar Nehustan (2 Koningen 18:4). Die naam wordt meestal uitgelegd als: een stuk koper. Zo laat Hizkia zien dat het geen heilig voorwerp is. De Heere Jezus wijst op dezelfde slang: ‘gelijk Mozes de slang in de woestijn verhoogd heeft, alzo moet de Zoon des mensen verhoogd worden’ (Johannes 3:14).",
        refs: ["Numeri 21:8–9", "2 Koningen 18:4", "Johannes 3:14"],
