        kop: "In die dagen",
        t: "Hoofdstuk 20 begint met ‘In die dagen’. De ziekte van Hizkia wordt na het verhaal van Sanherib verteld, maar de tekst zegt niet dat zij daarna kwam. God belooft hem namelijk dat Hij hem ‘uit de hand des konings van Assyrië verlossen’ zal, ‘mitsgaders deze stad’ (20:6). Daarom denken veel uitleggers dat Hizkia ziek werd vóór of tijdens de dreiging van Sanherib. Ook de gezanten uit Babel kwamen ‘te dier tijd’ (20:12). Volgens 2 Kronieken 32:31 kwamen zij vragen ‘naar dat wonderteken’, en ‘verliet hem God, om hem te verzoeken, om te weten al wat in zijn hart was’.",
