        t: "2 Kronieken 35 vertelt meer over Josia’s dood. Necho trok op ‘om te krijgen tegen Karchemis, aan den Frath’, en liet Josia zeggen: ‘ik ben heden tegen u niet’. Maar Josia ‘verstelde zich’ (hij vermomde zich) en ‘hoorde niet naar de woorden van Necho uit den mond van God’. Schutters raakten hem; hij stierf en werd in Jeruzalem begraven. Jeremia maakte een klaaglied over hem. Hulda had gezegd dat Josia ‘met vrede in uw graf verzameld’ zou worden, en dat hij het kwaad over Jeruzalem niet zou zien (2 Koningen 22:20). De verwoesting van de stad maakte hij inderdaad niet mee.",
